/* Growing film-photo constellation inspired by the supplied motion reference. */
(()=>{'use strict';const entry=document.getElementById('entry');if(!entry)return;
const canvas=document.createElement('canvas');canvas.className='journey-canvas';canvas.setAttribute('aria-hidden','true');entry.prepend(canvas);const ctx=canvas.getContext('2d');let photos=[],last=0,time=0,previous=0,wasClosed=true;const nodes=[];
// One origin, an irregular connected journey, then successively finer splits.
// Each branch starts only once its parent's travelling tip has arrived.
const skeleton=[[-.40,.35,-1],[-.26,.22,0],[-.11,.31,1],[.04,.20,2],[.23,.30,3],[.39,.15,4],[.33,-.05,5],[.43,-.27,6],[.23,-.34,7],[.07,-.24,8],[-.12,-.34,9],[-.31,-.26,10],[-.43,-.08,11],[-.29,.03,1],[-.12,-.04,13],[.08,.01,3]];
skeleton.forEach(([x,y,parent],i)=>nodes.push({x,y,parent,size:i%3===0?49:35,image:i,birth:parent<0?0:nodes[parent].birth+.63,phase:i*1.73,depth:0}));
for(let i=0;i<48;i++){const parent=i%16,p=nodes[parent],a=i*2.399+.4,r=.04+(i%4)*.017;nodes.push({x:p.x+Math.cos(a)*r,y:p.y+Math.sin(a)*r*1.3,size:20+(i%3)*5,image:(i+16)%26,parent,birth:p.birth+.9+(i%3)*.16,phase:i*1.39,depth:1})}
for(let i=0;i<144;i++){const parent=16+i%48,p=nodes[parent],a=i*2.399,r=.02+(i%3)*.012;nodes.push({x:p.x+Math.cos(a)*r,y:p.y+Math.sin(a)*r*1.3,size:8+(i%3)*4,image:(i*7)%26,parent,birth:p.birth+.8+(i%3)*.16,phase:i*2.13,depth:2})}
fetch('assets/journey/manifest.json').then(r=>r.json()).then(async films=>{photos=await Promise.all(films.map(f=>new Promise(resolve=>{const im=new Image();im.onload=()=>{const thumb=document.createElement('canvas');thumb.width=112;thumb.height=140;const c=thumb.getContext('2d'),s=Math.max(112/im.width,140/im.height),sw=112/s,sh=140/s;c.filter='sepia(.34) saturate(.48)';c.drawImage(im,(im.width-sw)/2,(im.height-sh)*.2,sw,sh,0,0,112,140);resolve(thumb)};im.onerror=()=>resolve(null);im.src=f.src})));time=0;entry.classList.add('journey-ready')}).catch(()=>{});
const ease=x=>1-Math.pow(1-Math.max(0,Math.min(1,x)),3);
function frame(now){requestAnimationFrame(frame);if(document.hidden||entry.hidden||entry.classList.contains('out')){previous=now;wasClosed=true;return}if(now-last<42)return;last=now;if(wasClosed){time=0;wasClosed=false}const reduced=document.body.classList.contains('reduced')||matchMedia('(prefers-reduced-motion: reduce)').matches;if(!reduced)time+=Math.min((now-(previous||now))/1000,.1);previous=now;if(!photos.length)return;
const w=entry.clientWidth,h=entry.clientHeight,dpr=Math.min(devicePixelRatio,1.5);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const t=reduced?12:time,zoom=1.1-.1*ease(t/16),sizeScale=Math.max(.58,Math.min(w/1100,1.25));
const positions=nodes.map(n=>({x:w*.5+(n.x*w+Math.sin(t*.14+n.phase)*5)*zoom,y:h*.5+(n.y*h+Math.cos(t*.12+n.phase)*4)*zoom,alpha:ease((t-n.birth-.58)/.7)}));
nodes.forEach((n,i)=>{if(n.parent<0)return;const p=positions[i],parent=positions[n.parent],growth=Math.max(0,Math.min(1,(t-n.birth)/.6));if(!growth)return;const dx=p.x-parent.x,dy=p.y-parent.y,bend=Math.sin(n.phase)*.23,cx=(parent.x+p.x)/2-dy*bend,cy=(parent.y+p.y)/2+dx*bend;
const curve=q=>({x:(1-q)*(1-q)*parent.x+2*(1-q)*q*cx+q*q*p.x,y:(1-q)*(1-q)*parent.y+2*(1-q)*q*cy+q*q*p.y});
ctx.strokeStyle=n.depth===0?'rgba(141,98,68,.52)':'rgba(153,113,82,.34)';ctx.lineWidth=n.depth===0?1.3:.65;ctx.beginPath();ctx.moveTo(parent.x,parent.y);for(let j=1;j<=24;j++){const v=curve(growth*j/24);ctx.lineTo(v.x,v.y)}ctx.stroke();
const q=growth<1?growth:(t*.17+n.phase)%1,v=curve(q);ctx.shadowColor='#d4a461';ctx.shadowBlur=growth<1?9:4;ctx.fillStyle=growth<1?'rgba(186,126,60,.9)':'rgba(186,126,60,.48)';ctx.beginPath();ctx.arc(v.x,v.y,growth<1?2.1:1.3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0});
nodes.forEach((n,i)=>{const p=positions[i],im=photos[n.image%photos.length];if(!im||!p.alpha)return;const s=n.size*sizeScale*(.72+.28*p.alpha),hh=s*1.25;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(n.phase)*.06+Math.sin(t*.08+n.phase)*.012);ctx.globalAlpha=p.alpha*(n.size>30?.76:.46);ctx.shadowColor='rgba(80,58,37,.15)';ctx.shadowBlur=n.size>30?9:3;ctx.fillStyle='#faf4e9';ctx.fillRect(-s/2-2,-hh/2-2,s+4,hh+4);ctx.shadowBlur=0;ctx.drawImage(im,-s/2,-hh/2,s,hh);ctx.restore()});
}requestAnimationFrame(frame);
})();
